#include <stdio.h>

#define SQUARE(x) ((x) * (x))

static int square_int(int value)
{
    return value * value;
}

int main(void)
{
    int a = 3;
    printf("macro=%d function=%d\n", SQUARE(a + 1), square_int(a + 1));
    return 0;
}

